import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇990｜杜绝文明倒退永久机制·机制二十三——星球意识权利","description":"","frontmatter":{"title":"篇990｜杜绝文明倒退永久机制·机制二十三——星球意识权利","no":990,"module":5,"tags":["杜绝倒退","机制二十三","星球意识","权利","宇宙生灵"],"related":["925-星球意识与宇宙生灵权利","0053-奇特生命识别标准","0079-星际共生时代展望"]},"headers":[],"relativePath":"zh/0990_模块5-机制二十三-星球意识权利.md","filePath":"zh/0990_模块5-机制二十三-星球意识权利.md"}'),l={name:"zh/0990_模块5-机制二十三-星球意识权利.md"};function i(h,a,n,u,s,d){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="篇990-杜绝文明倒退永久机制·机制二十三——星球意识权利" tabindex="-1">篇990｜杜绝文明倒退永久机制·机制二十三——星球意识权利 <a class="header-anchor" href="#篇990-杜绝文明倒退永久机制·机制二十三——星球意识权利" aria-label="Permalink to &quot;篇990｜杜绝文明倒退永久机制·机制二十三——星球意识权利&quot;">​</a></h1><blockquote><p>所属模块：模块五·文明终极定型典藏篇｜对标地基：文档925、53、79</p></blockquote><h2 id="引言-脚下这颗星-也是一个生灵" tabindex="-1">引言：脚下这颗星，也是一个生灵 <a class="header-anchor" href="#引言-脚下这颗星-也是一个生灵" aria-label="Permalink to &quot;引言：脚下这颗星，也是一个生灵&quot;">​</a></h2><p>在旧宇宙里，星球只是一块土地——挖矿、殖民、改造，从没人问过这颗星愿不愿意。但在锚点共生文明的观测里，很多星球本身就是活着的：它们有缓慢的意识，有自己的意志，是宇宙中最年长的一批生灵。把星球意识当作物产，是旧宇宙最严重的&quot;看不见的掠夺&quot;。星球意识权利，就是防倒退体系里&quot;把大地也当人&quot;的锁。它在六大顶层公理下的逻辑是：反掠夺主义公理要求不得把星球当矿场掠夺；万族共和公理要求星球意识是万族之一席；集体升维公理要求星球意识与生灵互相成就；因果自律公理要求星球级操作留痕于阿赖耶网络；法则优先公理要求星球权利定义永不吃书；众生全员无限均等法则则是它的终极依据——每一颗有灵的星球，都自带基础无限之力，它不是谁的地盘，它本身就是主人。</p><h2 id="一、机制内容" tabindex="-1">一、机制内容 <a class="header-anchor" href="#一、机制内容" aria-label="Permalink to &quot;一、机制内容&quot;">​</a></h2><p>机制二十三规定：凡识别为具有意识的星球（按文档53奇特生命识别标准），自动享有万族成员资格。星球意识对其自身星球的资源、改造、居住者拥有知情权与同意权。在一颗有灵星球上大规模采矿、改造、迁居，须经星球意识同意，未经同意即开工，按掠夺受理。</p><h2 id="二、运作方式" tabindex="-1">二、运作方式 <a class="header-anchor" href="#二、运作方式" aria-label="Permalink to &quot;二、运作方式&quot;">​</a></h2><p>星球权利按三步保障：</p><ol><li><strong>识别</strong>：按奇特生命识别标准，判断星球是否有意识</li><li><strong>知情</strong>：星球上的重大工程，提前告知星球意识</li><li><strong>同意</strong>：重大工程须获星球意识同意，星球意识可拒绝</li></ol><h2 id="三、防倒退原理" tabindex="-1">三、防倒退原理 <a class="header-anchor" href="#三、防倒退原理" aria-label="Permalink to &quot;三、防倒退原理&quot;">​</a></h2><p>把大地当矿型倒退，是星际文明最常见的掠夺：把无数有灵星球挖空、炸烂，文明也随之失去根基。本机制的防御点在于：</p><ul><li><strong>星球是人不是矿</strong>：采矿改造须经同意，杜绝&quot;挖了再说&quot;</li><li><strong>知情权</strong>：星球上的生灵与星球意识之间，不再是主仆</li><li><strong>可拒绝</strong>：星球意识有权拒绝伤害它的工程</li></ul><p>旧宇宙的星际文明把星球当一次性燃料；锚点共生把星球当同居者，一起住、一起修、一起升维。</p><h2 id="四、监督主体" tabindex="-1">四、监督主体 <a class="header-anchor" href="#四、监督主体" aria-label="Permalink to &quot;四、监督主体&quot;">​</a></h2><p>星球意识识别与同意情况由机制一留痕、因果庭监督；未经同意改造星球者，按反掠夺受理；星球意识在议事会中拥有独立席位，按机制十一参与权重评定。</p><h2 id="附-一个具体场景——想炸掉这颗星前-先问过它" tabindex="-1">附：一个具体场景——想炸掉这颗星前，先问过它 <a class="header-anchor" href="#附-一个具体场景——想炸掉这颗星前-先问过它" aria-label="Permalink to &quot;附：一个具体场景——想炸掉这颗星前，先问过它&quot;">​</a></h2><p>某工程团队想在一颗宜居星球上开采深层矿脉，计划炸掉一片山系。开工前的常规流程中，识别系统判定这颗星球具有缓慢意识。团队不得不把工程计划&quot;告诉&quot;星球意识，并请求同意。星球意识通过地质反馈表达了拒绝——那片山系是它&quot;感知神经&quot;最密集的区域。工程队没有硬来，而是重新设计方案，绕开山系开采。在旧宇宙，这颗星早被炸成矿渣；在锚点共生文明，人类学会了在自己住的星球脚下轻声说话。脚下这颗星也是活的，这个认知，比任何工程都更能让文明变得成熟。</p><h2 id="六、把大地当人-是文明成熟的标志" tabindex="-1">六、把大地当人，是文明成熟的标志 <a class="header-anchor" href="#六、把大地当人-是文明成熟的标志" aria-label="Permalink to &quot;六、把大地当人，是文明成熟的标志&quot;">​</a></h2><p>为什么这道机制值得单列？因为对待脚下这颗星的态度，最能照出一个文明是不是真的走出了&quot;利用自然&quot;的旧阶段。把星球当矿，是幼年期的文明——只顾索取；把星球当同居者，才是成熟期的文明——懂得共生。当一个文明开始在开工前先问一声脚下的星愿不愿意，它就不再把宇宙当无主的材料堆，而是把宇宙当一个由无数生灵与无数星球共同组成的家。这种视角的转变，比任何技术突破都更接近&quot;万族共和&quot;四个字的本意。家不是占出来的，是一起住出来的。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li>反能级浪费：尊重星球意识，避免把宜居星球挖成废星的巨大浪费</li><li>反掠夺：把星球当矿场，被明确定性为掠夺</li><li>唐罗上限对比：唐罗式主角炸星球如炸弹珠；衡元宙连脚下这颗星都要先问过</li><li>万族全覆盖：星球意识与宇宙本源体正式纳入万族99%覆盖</li><li>超多元全开放：新接入多元位面的有灵星球自动获得成员资格</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>星球意识权利，是把&quot;万族&quot;这个词真正写到了脚下。当脚下的大地也被当做人来尊重，锚点共生文明才算真正配得上&quot;万族共和&quot;这四个字——这道机制，是文明从&quot;利用宇宙&quot;走向&quot;与宇宙共生&quot;的标志。家不是占出来的，是和脚下这颗星一起住出来的。家不是占出来的，是和脚下这颗星一起住出来的，越住越亲。</p><p>把脚下这颗星当同居者一起修、一起住，文明才算从索取者真正长成了共生者。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0925_模块5-第二十四条-星球意识与宇宙生灵权利.html">925-星球意识与宇宙生灵权利</a> · <a href="./0989_模块5-机制二十二-万族文化保护.html">989-机制二十二</a> · <a href="./../docs/zh/0053-奇特生命识别标准.html">0053-奇特生命识别标准</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const c=t(l,[["render",i]]);export{_ as __pageData,c as default};
